import React, { useState, useRef } from "react";
import { useDB } from "../../context/DBContext";
import { useSchool } from "../../context/SchoolContext";
import { compressImage } from "../../utils/imageUtils";
import { getClasses, rankStudents, getGrade } from "../../utils/grades";
import StatsRow from "../../components/admin/StatsRow";
import AdminTabs from "../../components/admin/AdminTabs";
import ClassResultsTable from "../../components/admin/ClassResultsTable";
import Button from "../../components/common/Button";
import Card from "../../components/common/Card";
import Modal from "../../components/common/Modal";
import Input from "../../components/common/Input";
import SelectField from "../../components/common/SelectField";
import styles from "./AdminPage.module.css";

const BEHAVIOUR_ROWS = [
  "Punctuality","Attendance in Class","Attentiveness in Class",
  "Carrying out assignments","Participation in Sch. Activities",
  "Neatness","Honesty","Relationship with others",
  "Helping Others","Self Control","Games, Sports",
  "Handling of Tools, Lab & Workshop",
];
const GRADES_OPTS = ["A","B","C","D","E"];

export default function AdminPage({ toast, school = {} }) {
  const { db, updateDB } = useDB();
  const [activeTab, setActiveTab] = useState("students");
  const [classFilter, setClassFilter] = useState("");
  const [resultFilter, setResultFilter] = useState("");

  // Modals
  const [studentModal, setStudentModal] = useState(false);
  const [teacherModal, setTeacherModal] = useState(false);
  const [subjectModal, setSubjectModal] = useState(false);
  const [editStudentModal, setEditStudentModal] = useState(null); // student object
  const [affectiveModal, setAffectiveModal] = useState(null);     // student object
  const [rolesModal, setRolesModal] = useState(false);

  // New item forms
  const [newStudent, setNewStudent] = useState({ name: "", class: "" });
  const [newTeacher, setNewTeacher] = useState({ name: "", subject: "" });
  const [newSubject, setNewSubject] = useState("");

  // Edit student info form
  const [editInfo, setEditInfo] = useState({ admNo: "", sex: "", term: "" });

  // Affective draft
  const [affDraft, setAffDraft] = useState({});

  // Roles draft
  const [rolesDraft, setRolesDraft] = useState({ formMaster: "", houseMistress: "", principal: "" });

  const classes = getClasses(db.students);

  // ── Add / Delete helpers ────────────────────────────────────────────
  function addStudent() {
    const name = newStudent.name.trim();
    const cls  = newStudent.class.trim();
    if (!name) return toast("Student name is required.", "error");
    if (!cls)  return toast("Class is required.", "error");
    if (db.students.some((s) => s.name.toLowerCase() === name.toLowerCase()))
      return toast(`⚠️ Student "${name}" already exists!`, "error");
    updateDB((d) => { const id = Date.now().toString(); d.students.push({ id, name, class: cls }); d.scores[id] = {}; return d; });
    setNewStudent({ name: "", class: "" });
    setStudentModal(false);
    toast(`✅ Student "${name}" added.`);
  }

  function generateUniquePin() {
    const usedPins = new Set(db.teachers.map((t) => t.pin));
    let pin;
    let attempts = 0;
    do {
      // 6-digit PIN: 100000–999999
      pin = String(Math.floor(100000 + Math.random() * 900000));
      attempts++;
    } while (usedPins.has(pin) && attempts < 1000);
    return pin;
  }

  function addTeacher() {
    const name = newTeacher.name.trim();
    if (!name)               return toast("Teacher name is required.", "error");
    if (!newTeacher.subject) return toast("Please assign a subject.", "error");
    if (db.teachers.some((t) => t.name.toLowerCase() === name.toLowerCase()))
      return toast(`⚠️ Teacher "${name}" already exists!`, "error");
    const pin = generateUniquePin();
    updateDB((d) => { d.teachers.push({ id: Date.now().toString(), name, subject: newTeacher.subject, pin }); return d; });
    setNewTeacher({ name: "", subject: "" });
    setTeacherModal(false);
    toast(`✅ Teacher "${name}" added. Login PIN: ${pin}`);
  }

  function addSubject() {
    const name = newSubject.trim();
    if (!name) return toast("Subject name is required.", "error");
    if (db.subjects.some((s) => s.name.toLowerCase() === name.toLowerCase()))
      return toast(`⚠️ Subject "${name}" already exists!`, "error");
    updateDB((d) => { d.subjects.push({ id: Date.now().toString(), name }); return d; });
    setNewSubject(""); setSubjectModal(false);
    toast(`✅ Subject "${name}" added.`);
  }

  function deleteStudent(id) {
    if (!window.confirm("Delete this student and all their scores?")) return;
    updateDB((d) => { d.students = d.students.filter((s) => s.id !== id); delete d.scores[id]; return d; });
    toast("Student removed.", "info");
  }
  function deleteTeacher(id) {
    if (!window.confirm("Delete this teacher?")) return;
    updateDB((d) => { d.teachers = d.teachers.filter((t) => t.id !== id); return d; });
    toast("Teacher removed.", "info");
  }
  function deleteSubject(id) {
    if (!window.confirm("Delete this subject? All scores for it will be removed.")) return;
    updateDB((d) => { d.subjects = d.subjects.filter((s) => s.id !== id); Object.keys(d.scores).forEach((sid) => delete d.scores[sid][id]); return d; });
    toast("Subject removed.", "info");
  }
  function toggleLock() {
    updateDB((d) => { d.locked = !d.locked; return d; });
    toast(db.locked ? "🔓 Results unlocked!" : "🔒 Results locked!", db.locked ? "success" : "error");
  }

  // ── Edit student info ───────────────────────────────────────────────
  function openEditStudent(student) {
    const info = (db.studentInfo || {})[student.id] || {};
    setEditInfo({ admNo: info.admNo || "", sex: info.sex || "", term: info.term || "" });
    setEditStudentModal(student);
  }
  function saveStudentInfo() {
    updateDB((d) => {
      if (!d.studentInfo) d.studentInfo = {};
      d.studentInfo[editStudentModal.id] = { admNo: editInfo.admNo, sex: editInfo.sex, term: editInfo.term };
      return d;
    });
    setEditStudentModal(null);
    toast("✅ Student info saved.");
  }

  // ── Affective ratings ───────────────────────────────────────────────
  function openAffective(student) {
    const existing = (db.affective || {})[student.id] || {};
    setAffDraft({ ...existing });
    setAffectiveModal(student);
  }
  function saveAffective() {
    updateDB((d) => {
      if (!d.affective) d.affective = {};
      d.affective[affectiveModal.id] = { ...affDraft };
      return d;
    });
    setAffectiveModal(null);
    toast("✅ Ratings saved.");
  }

  // ── Roles ───────────────────────────────────────────────────────────
  function openRoles() {
    setRolesDraft({ ...db.roles });
    setRolesModal(true);
  }
  function saveRoles() {
    updateDB((d) => { d.roles = { ...rolesDraft }; return d; });
    setRolesModal(false);
    toast("✅ Role assignments saved.");
  }

  // ── Print ───────────────────────────────────────────────────────────
  function printResults() {
    if (!classes.length) return toast("No students to print.", "error");

    // School profile from Firestore (passed in via props)
    const schoolName    = school.schoolName    || "School Name";
    const schoolAddress = school.address       || "";
    const schoolLogo    = school.logo          || ""; // base64 dataURL or ""
    const principalName = school.principalName || "";

    const classRankings = {};
    classes.forEach((cls) => {
      classRankings[cls] = rankStudents(db.students.filter((s) => s.class === cls), db.scores);
    });

    const css = `
      @page { size: A4 portrait; margin: 10mm; }
      * { box-sizing: border-box; margin: 0; padding: 0; }
      body { font-family: Arial, sans-serif; font-size: 11px; color: #000; background: #fff; }
      .page { width: 100%; page-break-after: always; padding: 4px; }
      .page:last-child { page-break-after: avoid; }
      .school-header { display: flex; align-items: center; justify-content: center; gap: 16px; border-bottom: 3px double #000; padding-bottom: 8px; margin-bottom: 4px; }
      .school-logo-wrap { width: 70px; height: 70px; flex-shrink: 0; display: flex; align-items: center; justify-content: center; }
      .school-logo-img { width: 70px; height: 70px; border-radius: 50%; object-fit: cover; border: 2px solid #000; display: block; }
      .school-logo-text { width: 70px; height: 70px; border: 2px solid #000; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 9px; font-weight: bold; text-align: center; padding: 6px; word-break: break-word; line-height: 1.2; }
      .school-name { text-align: center; }
      .school-name h1 { font-size: 17px; font-weight: 900; text-transform: uppercase; letter-spacing: 1px; line-height: 1.2; text-align: center; }
      .school-name .address { font-size: 10.5px; margin-top: 2px; text-align: center; }
      .report-title { text-align: center; font-size: 13px; font-weight: bold; text-decoration: underline; text-transform: uppercase; margin: 5px 0; letter-spacing: 0.5px; }
      .info-grid { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr; border: 1px solid #000; }
      .info-row2 { display: grid; grid-template-columns: 1fr 1fr 1fr; border: 1px solid #000; border-top: none; }
      .info-cell { padding: 3px 6px; border-right: 1px solid #000; font-size: 10.5px; }
      .info-cell:last-child { border-right: none; }
      .info-line { display: inline-block; min-width: 60px; border-bottom: 1px solid #000; }
      .section-title { background: #000; color: #fff; text-align: center; font-weight: bold; font-size: 11px; padding: 3px; text-transform: uppercase; letter-spacing: 1px; margin-top: 6px; }
      .cognitive-table { width: 100%; border-collapse: collapse; font-size: 10px; }
      .cognitive-table th, .cognitive-table td { border: 1px solid #000; padding: 2px 4px; text-align: center; vertical-align: middle; }
      .cognitive-table .subject-col { text-align: left; }
      .cognitive-table thead th { background: #d0d0d0; font-weight: bold; font-size: 9.5px; }
      .cognitive-table tbody tr { height: 17px; }
      .cognitive-table .total-row td { font-weight: bold; background: #ebebeb; }
      .sig-img { height: 32px; max-width: 90px; object-fit: contain; display: block; margin: auto; }
      .bottom-section { display: flex; gap: 6px; margin-top: 6px; }
      .bottom-left { flex: 1.6; }
      .bottom-right { flex: 1; }
      .summary-line { display: flex; align-items: flex-end; gap: 4px; margin-bottom: 5px; font-size: 10.5px; }
      .summary-label { white-space: nowrap; font-weight: bold; }
      .summary-value { flex: 1; border-bottom: 1px solid #000; min-width: 60px; }
      .comment-block { margin-bottom: 6px; font-size: 10px; }
      .comment-label { font-weight: bold; }
      .comment-text { border-bottom: 1px solid #000; min-height: 14px; margin: 2px 0; font-size: 10px; }
      .comment-line { border-bottom: 1px solid #000; height: 14px; margin: 2px 0; }
      .sig-row { display: flex; justify-content: flex-end; align-items: flex-end; gap: 4px; margin-top: 2px; font-size: 9px; }
      .sig-line { border-bottom: 1px solid #000; width: 100px; }
      .affective-title { background: #000; color: #fff; text-align: center; font-weight: bold; font-size: 9px; padding: 2px; text-transform: uppercase; letter-spacing: 0.5px; }
      .affective-table { width: 100%; border-collapse: collapse; font-size: 9px; }
      .affective-table th, .affective-table td { border: 1px solid #000; padding: 2px 3px; text-align: center; }
      .affective-table .act-col { text-align: left; font-size: 9px; }
      .affective-table thead th { background: #d0d0d0; font-weight: bold; }
      .affective-table tbody tr { height: 14px; }
      .rating-key { font-size: 8px; margin-top: 3px; line-height: 1.5; }
      .promoted-row { margin-top: 8px; font-size: 10.5px; font-weight: bold; border-top: 1px solid #000; padding-top: 4px; }
      .principal-sig { text-align: right; margin-top: 6px; font-size: 10px; border-top: 1px solid #000; padding-top: 4px; }
    `;

    let pages = "";

    db.students.forEach((student) => {
      const cls = student.class;
      const ranked = classRankings[cls] || [];
      const studentRank = ranked.find((r) => r.id === student.id);
      const position = studentRank ? studentRank.pos : "—";
      const totalStudents = ranked.length;
      const info = (db.studentInfo || {})[student.id] || {};
      const staffC = (db.staffComments || {})[student.id] || {};
      const affData = (db.affective || {})[student.id] || {};

      let subjectRows = "";
      let grandTotal = 0;

      db.subjects.forEach((sub) => {
        const sc = (db.scores[student.id] || {})[sub.id] || {};
        const tc = (db.teacherComments?.[student.id] || {})[sub.id] || {};
        const t1   = sc.t1   !== undefined ? Number(sc.t1)   : "";
        const t2   = sc.t2   !== undefined ? Number(sc.t2)   : "";
        const exam = sc.exam !== undefined ? Number(sc.exam) : "";
        const total = (Number(t1) || 0) + (Number(t2) || 0) + (Number(exam) || 0);
        const hasScore = sc.t1 !== undefined;
        if (hasScore) grandTotal += total;
        const pct = hasScore ? total : "";
        const grade = hasScore ? getGrade(total).letter : "";
        const sigImg = tc.signature ? `<img src="${tc.signature}" class="sig-img" alt="sig"/>` : "";

        subjectRows += `<tr>
          <td class="subject-col">${sub.name}</td>
          <td>${t1 !== "" ? t1 : ""}</td>
          <td>${t2 !== "" ? t2 : ""}</td>
          <td>${exam !== "" ? exam : ""}</td>
          <td>${hasScore ? total : ""}</td>
          <td></td>
          <td>${grade}</td>
          <td style="font-size:9px;text-align:left">${tc.comment || ""}</td>
          <td>${sigImg}</td>
        </tr>`;
      });

      const scoredSubjects = db.subjects.filter((sub) => (db.scores[student.id] || {})[sub.id]?.t1 !== undefined).length;
      const maxPossible = scoredSubjects * 100;
      const avgPct = maxPossible > 0 ? ((grandTotal / maxPossible) * 100).toFixed(1) : "";

      const affRows = BEHAVIOUR_ROWS.map((b) => {
        const rating = affData[b] || "";
        const cells = GRADES_OPTS.map((g) =>
          `<td style="${rating === g ? "background:#000;color:#fff;font-weight:bold" : ""}">${rating === g ? g : ""}</td>`
        ).join("");
        return `<tr><td class="act-col">${b}</td>${cells}</tr>`;
      }).join("");

      pages += `<div class="page">
        <div class="school-header">
          <div class="school-logo-wrap">
            ${schoolLogo
              ? `<img src="${schoolLogo}" class="school-logo-img" alt="logo"/>`
              : `<div class="school-logo-text">${schoolName.substring(0, 10)}</div>`
            }
          </div>
          <div class="school-name">
            <h1>${schoolName.toUpperCase()}</h1>
            <div class="address">${schoolAddress}</div>
            ${principalName ? `<div class="address" style="font-weight:bold;">Principal: ${principalName}</div>` : ""}
          </div>
        </div>
        <div class="report-title">Students Termly Report Sheet</div>

        <div class="info-grid">
          <div class="info-cell">Name: <span class="info-line">${student.name}</span></div>
